const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const roles=['admin','reception','technician','pathologist','billing','auditor'];
const label=s=>String(s||'').replace(/_/g,' ').replace(/^./,c=>c.toUpperCase());
const badge=(value,good=false)=>`<span class="badge ${good?'Approved':'Review'}">${esc(value)}</span>`;
export function loginScreen(message=''){return `<main class="login-screen"><section class="login-story"><div class="login-brand">▤ labflow.</div><span class="eyebrow">YOUR LABORATORY WORKSPACE</span><h1>Every result deserves<br>a reliable process.</h1><p>Patients, specimens, reviewed reports, and billing—connected to your laboratory’s shared database.</p><div class="login-points"><span>✓ Named staff access</span><span>✓ Reviewed report release</span><span>✓ Traceable activity</span></div></section><section class="login-card"><div class="login-card-inner"><span class="eyebrow">WELCOME BACK</span><h2>Sign in to your laboratory</h2><p>Use your individual staff account.</p><form id="login-form"><div class="field"><label for="login-user">Username</label><input id="login-user" name="username" required autocomplete="username" maxlength="100" autofocus></div><div class="field"><label for="login-password">Password</label><input id="login-password" name="password" type="password" required autocomplete="current-password"></div><div id="login-error" class="error-text" role="alert">${esc(message)}</div><button class="btn primary" type="submit">Sign in securely →</button></form><small>Account access is managed by your laboratory administrator.</small></div></section></main>`;}
export function adminPage({page,mode,session={},staff=[],audit=[],readiness={},instruments=[],deliveries=[],controls={}}){
 if(page==='Team & access')return `<div class="ops-intro"><strong>Individual access. Clear responsibility.</strong><p>Reception registers patients; technicians enter results; authorized reviewers release reports. Permissions are enforced by the server.</p></div><section class="panel"><div class="panel-head"><div><h2>Laboratory staff</h2><p class="panel-sub">${mode==='demo'?'Connect the self-hosted server to manage real staff.':'Disabled accounts cannot start or retain sessions.'}</p></div><button class="btn primary" data-action="new-user" ${mode==='demo'?'disabled':''}>+ Add staff member</button></div><div class="table-wrap"><table><thead><tr><th>STAFF MEMBER</th><th>USERNAME</th><th>ROLE</th><th>ACCESS</th><th>ACTION</th></tr></thead><tbody>${staff.length?staff.map(u=>`<tr><td>${esc(u.displayName)}</td><td>${esc(u.username)}</td><td>${esc(label(u.role))}</td><td>${badge(u.disabled?'Disabled':'Active',!u.disabled)}</td><td>${u.id===session.user?.id?'<span class="muted">Your account</span>':`<button class="link-btn" data-action="toggle-user" data-id="${esc(u.id)}" data-disabled="${u.disabled?'0':'1'}">${u.disabled?'Enable':'Disable'}</button>`}</td></tr>`).join(''):'<tr><td colspan="5" class="empty">No staff records loaded.</td></tr>'}</tbody></table></div></section><div class="role-grid">${roles.map(r=>`<article class="panel role-card"><h3>${label(r)}</h3><p>${{admin:'Manage staff, settings and operations. Review rules still apply.',reception:'Register patients and record sample collection.',technician:'Process samples and enter results for review.',pathologist:'Review findings and authorize report release.',billing:'Record payments and view invoice balances.',auditor:'Read records and inspect the activity trail.'}[r]}</p></article>`).join('')}</div>`;
 if(page==='Audit trail')return `<section class="panel"><div class="panel-head"><div><h2>Recorded laboratory activity</h2><p class="panel-sub">Named actions, timestamps and before/after history.</p></div><button class="btn" data-action="refresh-admin">Refresh</button></div><div class="table-wrap"><table><thead><tr><th>TIME (LOCAL)</th><th>ACTION</th><th>RECORD</th><th>STAFF ID</th><th>DETAILS</th></tr></thead><tbody>${audit.length?audit.map(a=>`<tr><td>${esc(new Date(a.at).toLocaleString('en-IN'))}</td><td>${esc(a.type)}</td><td>${esc(a.order_id||a.orderId||'Workspace')}</td><td>${esc(a.actor)}</td><td><button class="link-btn" data-action="audit-detail" data-id="${esc(a.id)}">View change</button></td></tr>`).join(''):'<tr><td colspan="5" class="empty">No audit entries loaded.</td></tr>'}</tbody></table></div></section>`;
 if(page==='Quality controls')return `<div class="ops-intro"><strong>QC evidence, with a real release hold.</strong><p>Capture the lab’s actual control-run decision and supporting record. A rejected or expired accepted run blocks affected report release. Missing policy is shown as unconfigured, never as a successful control.</p></div><section class="panel"><div class="panel-head"><div><h2>Test control status</h2><p class="panel-sub">Controls are recorded by named staff and retained in the audit trail.</p></div><button class="btn primary" data-action="record-qc" ${mode==='demo'?'disabled':''}>+ Record QC run</button></div><div class="table-wrap"><table><thead><tr><th>PANEL</th><th>STATE</th><th>RUN ID</th><th>VALID UNTIL</th><th>ACTION</th></tr></thead><tbody>${Object.entries(controls).map(([code,c])=>{const pass=c.status==='accepted'&&new Date(c.expiresAt)>new Date();return `<tr><td>${esc(code)}</td><td>${badge(pass?'Accepted':c.status==='accepted'?'Expired':'Hold',pass)}</td><td>${esc(c.runId)}</td><td>${esc(c.expiresAt?new Date(c.expiresAt).toLocaleString('en-IN'):'Not accepted')}</td><td><button class="link-btn" data-action="record-qc" data-code="${esc(code)}">Record new run</button></td></tr>`;}).join('')||'<tr><td colspan="5" class="empty">No control-run evidence has been recorded. Configure the laboratory’s QC policy before clinical use.</td></tr>'}</tbody></table></div></section>`;
 if(page==='Readiness')return `<section class="readiness-hero"><div><span class="eyebrow">INDIA · DESIGN TARGET: 100 PATIENTS / DAY</span><h2>${mode==='demo'?'A demonstration, with a clear path to deployment.':readiness.ready?'Engineering checks are passing.':'Complete your deployment checks.'}</h2><p>${mode==='demo'?'The hosted preview uses device-local fictional records. Clinical work needs the shared server, named staff, validated methods, and tested operations.':'These are engineering checks, not clinical approval or certification. Your laboratory must validate its methods, instruments and release procedures.'}</p></div>${badge(readiness.ready&&mode==='server'?'Checks passing':'Setup required',readiness.ready&&mode==='server')}</section><div class="readiness-grid">${(readiness.checks||demoChecks()).map(c=>`<article class="panel readiness-card"><span class="readiness-symbol ${c.pass?'pass':''}">${c.pass?'✓':'○'}</span><div><h3>${esc(c.name||c.label||c.id)}</h3><p>${esc(c.detail||c.message||'')}</p></div>${badge(c.pass?'Verified':'Pending',c.pass)}</article>`).join('')}</div><section class="panel settings-panel" style="margin-top:22px"><h2>Built from a real comparison</h2><p class="muted" style="line-height:1.9;margin:12px 0">Our comparison of CrelioHealth, MocDoc, Labsmart and SENAITE separates advertised capabilities, working Labflow features, and remaining gaps.</p><a class="btn" href="/competition-and-readiness.html" target="_blank" rel="noopener">Read the research & deployment plan ↗</a></section>`;
 if(page==='Integrations')return `<section class="ops-intro"><strong>Controlled imports. Verified delivery status.</strong><p>Each analyzer needs a validated mapping. CSV imports create reviewable draft results; they never approve a report. Delivery requests remain blocked until a provider is configured.</p></section><div class="settings-grid"><section class="panel settings-panel"><div class="ops-title"><h2>Analyzer mappings</h2><button class="btn" data-action="new-instrument" ${mode==='demo'?'disabled':''}>+ Mapping</button></div>${instruments.map(i=>`<div class="integration"><div><h3>${esc(i.name||i.id)}</h3><p>${esc(i.id)} · ${Object.keys(i.mappings||{}).length} test mappings</p></div><div>${badge(i.enabled?'Enabled':'Disabled',i.enabled)}<button class="link-btn" style="margin-top:8px" data-action="toggle-instrument" data-id="${esc(i.id)}">${i.enabled?'Disable':'Enable'}</button></div></div>`).join('')||'<div class="empty">No analyzer is connected. Add and validate a mapping before importing results.</div>'}<button class="btn primary" data-action="analyzer-import" ${mode==='demo'||!instruments.some(i=>i.enabled)?'disabled':''}>Import analyzer CSV</button><p class="muted" style="font-size:11px;line-height:1.8;margin-top:14px">Generic CSV support does not establish compatibility with every analyzer. ASTM/HL7 and serial/TCP middleware need device-specific implementation and acceptance tests.</p></section><section class="panel settings-panel"><h2>Report delivery queue</h2><div class="notice">WhatsApp and email providers are not connected. Queued requests are not sent and are never marked delivered.</div>${deliveries.slice(0,8).map(d=>`<div class="integration"><div><h3>${esc(d.channel)} · ${esc(d.orderId)}</h3><p>${esc(d.destination)}</p></div>${badge(d.status==='blocked'?'Provider required':d.status)}</div>`).join('')||'<p class="muted">No delivery requests yet.</p>'}<p class="muted" style="font-size:11px;line-height:1.8;margin-top:16px">Record recipient consent and queue an approved report from the patient record. Provider integration must add secure report links, retries and authenticated delivery receipts.</p></section></div>`;
 return '';
}
function demoChecks(){return [{name:'Shared persistent database',detail:'The published preview is browser-local. Use the included server for shared records.',pass:false},{name:'Named staff and separate reviewer',detail:'Create individual accounts and test role permissions on the server.',pass:false},{name:'HTTPS and protected sessions',detail:'Configure the production origin and HTTPS reverse proxy.',pass:false},{name:'Encrypted backup and tested restore',detail:'Run the included backup and restore verification commands.',pass:false},{name:'Lab-validated catalog and methods',detail:'A qualified lab must validate intervals, methods, critical thresholds and printouts.',pass:false},{name:'Analyzer and delivery acceptance',detail:'Actual device models and WhatsApp/email provider credentials are required.',pass:false}];}
export function staffForm(){return `<form id="staff-form"><div class="field"><label>Full name *</label><input name="displayName" required maxlength="100"></div><div class="field"><label>Username *</label><input name="username" required maxlength="64" autocomplete="off"></div><div class="field"><label>Role</label><select name="role">${roles.map(r=>`<option>${r}</option>`).join('')}</select></div><div class="field"><label>Initial password *</label><input name="password" type="password" required minlength="16" autocomplete="new-password"></div><p class="muted" style="font-size:11px;line-height:1.8">Use a unique password and share it securely with that staff member. Do not use a common laboratory login.</p><div id="staff-error" class="error-text"></div></form>`;}
